const PACK_TO_DATASET: Readonly<Record<string, string>> = {
  pulsoicon: 'tabler',
  iconsax: 'iconsax',
  hugeicons: 'hugeicons',
  itshover: 'itshover',
  tabler: 'tabler',
  aicanvas: 'ph',
  phosphor: 'ph',
  heroicons: 'humbleicons',
  humbleicons: 'humbleicons',
  majesticons: 'majesticons',
  dooicons: 'solar',
}

export const ICON_PACK_META_MAP: Readonly<Record<string, IconPackMeta>> = Object.fromEntries(
  ICON_PACK_CATALOG.map((p) => [p.id, p]),
)

export function resolveVectorGlyph(pack: string, slot: string): VectorGlyph | null {
  const datasetKey = PACK_TO_DATASET[pack]
  if (!datasetKey) return null
  return VECTOR_DATASETS[datasetKey]?.[slot] ?? VECTOR_DATASETS.tabler?.[slot] ?? null
}
